// ---- Calendar (.ics) export: every planned session on its real date, with a morning alarm ----
function pad2(n) { return (n < 10 ? "0" : "") + n; }
function icsDate(dt) { return "" + dt.getUTCFullYear() + pad2(dt.getUTCMonth() + 1) + pad2(dt.getUTCDate()); }
