function removeExtra(id) { EXTRA = EXTRA.filter((e) => e.id !== id); saveExtra(); try { syncWatch(); } catch (e) {} try { syncNativeReminders(); } catch (e) {} }
function extrasOn(iso) { return EXTRA.filter((e) => e.date === iso); }
