  const dots = weeks.map((w, i) =>
    '<circle cx="' + x(i) + '" cy="' + y(w.km) + '" r="' + (i === weeks.length - 1 ? 4 : 2.6) + '" class="lt-dot' + (i === weeks.length - 1 ? " now" : "") + '"/>').join("");
