  "race-specific": { k: "quality", lab: "Quality", c: "var(--eff-hard)", ic: "rIntervals" },
  race: { k: "quality", lab: "Quality", c: "var(--eff-hard)", ic: "rRace" },
  strides: { k: "quality", lab: "Quality", c: "var(--eff-hard)", ic: "rStrides" },
