  const nm = sh ? sh.name || "" : "";
  const start = sh ? Math.round(Number(sh.baseKm) || 0) : 0;
  const ret = sh ? Math.round(Number(sh.retireKm) || SHOE_DEFAULT_RETIRE_KM) : SHOE_DEFAULT_RETIRE_KM;
