// ============ LIVE SESSION (in-app) ========================================
const KIND_COLOR = { warmup: "var(--base)", cooldown: "var(--base)", steady: "var(--base)", recovery: "var(--taper)", rep: "var(--peak)" };
let LIVE = null;
const GPS_AVAILABLE = typeof navigator !== "undefined" && "geolocation" in navigator;
