// The runner's first name (from their profile) for personalised coaching, or "" if not set.
function firstName() { const n = (profile.name || "").trim(); return n ? n.split(" ")[0] : ""; }
function nameTail() { const n = firstName(); return n ? ", " + n : ""; }
